import{_ as e,c as o,ag as s,o as r}from"./chunks/framework.-a8jReyC.js";const m=JSON.parse('{"title":"Fluxo de Caixa","description":"","frontmatter":{"title":"Fluxo de Caixa"},"headers":[],"relativePath":"features/cashflow.md","filePath":"features/cashflow.md"}'),t={name:"features/cashflow.md"};function i(l,a,n,d,c,p){return r(),o("div",null,a[0]||(a[0]=[s('<h1 id="📈-fluxo-de-caixa" tabindex="-1">📈 Fluxo de Caixa <a class="header-anchor" href="#📈-fluxo-de-caixa" aria-label="Permalink to &quot;📈 Fluxo de Caixa&quot;">​</a></h1><p>O módulo de <strong>Fluxo de Caixa</strong> é o seu painel de análise financeira. Ele reúne em um só lugar o gráfico mensal, os relatórios por categoria e as projeções — para você entender para onde vai o seu dinheiro.</p><h2 id="visao-geral" tabindex="-1">Visão Geral <a class="header-anchor" href="#visao-geral" aria-label="Permalink to &quot;Visão Geral&quot;">​</a></h2><p>O Fluxo de Caixa organiza suas finanças em três níveis de detalhe:</p><ul><li><strong>Ano:</strong> visão completa do ano, com totais, projeções e os 12 meses.</li><li><strong>Mês:</strong> detalhe do mês selecionado, com as transações do período.</li><li><strong>Dia:</strong> transações de um dia específico.</li></ul><h2 id="grafico-mensal" tabindex="-1">Gráfico Mensal <a class="header-anchor" href="#grafico-mensal" aria-label="Permalink to &quot;Gráfico Mensal&quot;">​</a></h2><p>Um dos destaques do Fluxo de Caixa é o <strong>gráfico mensal</strong>, que mostra as <strong>entradas</strong> e <strong>saídas</strong> de cada mês do ano:</p><ul><li>Barras verdes = entradas (receitas).</li><li>Barras vermelhas = saídas (despesas).</li><li>Ao passar o mouse sobre um mês, você vê o resultado líquido.</li></ul><p>Isso dá uma leitura rápida de como seu fluxo financeiro evolui ao longo do ano — onde você ganha mais, onde gasta mais e em quais meses o resultado é positivo ou negativo.</p><h2 id="analise-por-categoria" tabindex="-1">Análise por Categoria <a class="header-anchor" href="#analise-por-categoria" aria-label="Permalink to &quot;Análise por Categoria&quot;">​</a></h2><p>Descubra quais categorias mais impactam suas finanças:</p><ul><li><strong>Totais por categoria:</strong> quanto entra e sai em cada categoria.</li><li><strong>Principais transações:</strong> os maiores lançamentos.</li><li><strong>Comparativo e variação</strong> (planos com relatório avançado): variação entre períodos e insights.</li></ul><h3 id="niveis-de-acesso" tabindex="-1">Níveis de acesso <a class="header-anchor" href="#niveis-de-acesso" aria-label="Permalink to &quot;Níveis de acesso&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recurso</th><th>Essencial</th><th>Equilíbrio Total</th></tr></thead><tbody><tr><td>Análise por categoria (totais e principais)</td><td>✔️</td><td>✔️</td></tr><tr><td>Relatórios avançados (variação, comparativo, insights)</td><td>🔒</td><td>✔️</td></tr><tr><td>Exportação XLSX</td><td>🔒</td><td>✔️</td></tr></tbody></table><h2 id="projecoes" tabindex="-1">Projeções <a class="header-anchor" href="#projecoes" aria-label="Permalink to &quot;Projeções&quot;">​</a></h2><p>Com base na sua média mensal, o Fluxo de Caixa projeta:</p><ul><li><strong>Taxa de economia:</strong> quanto você poupa em relação ao que ganha.</li><li><strong>Média mensal:</strong> seu resultado médio por mês.</li><li><strong>Saldo projetado:</strong> estimativa para os próximos meses.</li></ul><h2 id="exportacao-para-xlsx" tabindex="-1">Exportação para XLSX <a class="header-anchor" href="#exportacao-para-xlsx" aria-label="Permalink to &quot;Exportação para XLSX&quot;">​</a></h2><p>No plano <strong>Equilíbrio Total</strong>, você pode exportar suas transações e análises para Excel (XLSX), ideal para arquivar, compartilhar ou processar em planilhas.</p><hr><p>O Fluxo de Caixa é o lugar certo para avaliar sua saúde financeira. Combine com a <a href="/features/import-transactions.html">importação de faturas</a> para manter os dados sempre atualizados sem esforço.</p>',21)]))}const h=e(t,[["render",i]]);export{m as __pageData,h as default};
